from pathlib import Path
p=Path('frontend/src/components/AiQuestionWorkbench.vue');s=p.read_text(encoding='utf-8-sig')
s=s.replace('const busy=ref(false)',"const editOpen=ref(false),saving=ref(false),edit=reactive<any>({stem:'',options:[],answer:'',explanation:'',note:''})\nfunction startRevision(){const q=current.value;if(!q)return;edit.stem=q.stem;edit.options=JSON.parse(JSON.stringify(q.options||[]));edit.answer=q.answer_payload?.key??q.answer_payload?.keys??q.answer_payload?.value??q.answer_payload?.numeric;edit.explanation=q.explanation||'';edit.note='';editOpen.value=true}\nasync function saveRevision(){const q=current.value;if(!q)return;const type=q.question_type,choices=edit.options.map((o:any)=>o.key);const answers=Array.isArray(edit.answer)?edit.answer:[edit.answer];if(!edit.stem.trim()||!edit.explanation.trim()||(['single_choice','multi_choice'].includes(type)&&(!edit.options.length||edit.options.some((o:any)=>!o.text.trim())||!answers.length||answers.some((k:any)=>!choices.includes(k))))){ElMessage.warning('请补齐题干、选项、答案和解析');return}saving.value=true;try{const answer={...q.answer_payload};if(type==='single_choice')answer.key=edit.answer;else if(type==='multi_choice')answer.keys=edit.answer;else if(type==='numeric'&&'numeric' in answer)answer.numeric=Number(edit.answer);else answer.value=edit.answer;await api.post(`/admin/questions/${q.question_id}/revise`,{patch:{stem:edit.stem.trim(),options:edit.options,answer_payload:answer,explanation:edit.explanation.trim(),notes:`${q.notes||''}\\n教师内容修订：${edit.note||'已核对题干条件、答案与解析一致。'}`}});await loadQuestions();emit('changed');editOpen.value=false;ElMessage.success('修订已保存为新版本')}catch(e){ElMessage.error(friendlyError(e,'修订未保存'))}finally{saving.value=false}}\nconst busy=ref(false)",1)
s=s.replace('<el-button v-if="current.review_status', '<el-button @click="startRevision">修订内容</el-button><el-button v-if="current.review_status',1)
s=s.replace(' </el-dialog>\n</template>', ''' </el-dialog>
 <el-dialog v-model="editOpen" title="修订候选题" width="min(760px, 94vw)" top="4vh" :close-on-click-modal="false"><div class="revision-form"><label>题干<el-input v-model="edit.stem" type="textarea" :rows="4" /></label><div class="revision-options"><label v-for="o in edit.options" :key="o.key">选项 {{ o.key }}<el-input v-model="o.text" type="textarea" :rows="2" /></label></div><label>参考答案<el-select v-if="['single_choice','multi_choice'].includes(current?.question_type)" v-model="edit.answer" :multiple="current?.question_type==='multi_choice'" aria-label="修订参考答案"><el-option v-for="o in edit.options" :key="o.key" :value="o.key" :label="o.key" /></el-select><el-select v-else-if="current?.question_type==='true_false'" v-model="edit.answer"><el-option :value="true" label="正确" /><el-option :value="false" label="错误" /></el-select><el-input-number v-else v-model="edit.answer" /></label><label>解析<el-input v-model="edit.explanation" type="textarea" :rows="3" /></label><label>修订依据<el-input v-model="edit.note" placeholder="记录核对依据" /></label></div><template #footer><el-button @click="editOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveRevision">保存新版本</el-button></template></el-dialog>
</template>''')
s+='\n<style scoped>.revision-form{display:grid;gap:14px;max-height:calc(88dvh - 140px);overflow:auto;padding-right:6px}.revision-form label{display:grid;gap:7px;font-size:14px;color:#496888}.revision-options{display:grid;grid-template-columns:1fr 1fr;gap:12px}.revision-form :deep(textarea){font-size:15px;line-height:1.6}.revision-form .el-select{width:160px}.candidate-detail>.el-button{margin-top:8px}@media(max-width:600px){.revision-options{grid-template-columns:1fr}}</style>\n'
p.write_text(s,encoding='utf-8')
